/* machine.c lbl_1_data_150/200/2B0/360/430 via lbl_1_data_4E0[partType]: one garage part
 * (partType 0 body, 1 tire, 2 ?, 3 char, 4 hook-ish; see machine.c) */
typedef struct SdPartData_s {
    u32 mesNo;   /* 0x0: HuWinMesSet (part name) */
    u32 unk4;    /* 0x4: message id */
    u32 unk8;    /* 0x8: DATANUM */
    u8 point;    /* 0xC: compared against GwCommon.sdPoint[partType] (fn_1_414C) */
    s8 unkD[3];  /* 0xD: address taken in garage/desk */
} SDPARTDATA; /* 0x10 */

/* machine.c lbl_1_data_768: body model table (fn_1_51C4) */
typedef struct SdBodyData_s {
    u32 dataNum; /* 0x0 */
    s32 unk4;
    s32 unk8;
    s32 unkC;
    float unk10;
    float unk14;
    s32 unk18;
} SDBODYDATA; /* 0x1C */

/* machine.c lbl_1_data_500: tire model table (fn_1_521C, fn_1_5390) */
typedef struct SdTireData_s {
    u32 dataNum[4]; /* 0x0: one model per wheel */
    s32 unk10;
    s32 unk14;
    s32 unk18;
    float unk1C;    /* 0x1C: body height offset (fn_1_5390) */
    float unk20;    /* 0x20: added for the 1-wheel type */
    float unk24;
    float unk28;
    float unk2C;
    float unk30;
    s32 unk34;      /* 0x34: low nibble = wheel layout (0: 4, 1: 2, 2: 1) */
} SDTIREDATA; /* 0x38 */

/* machine.c lbl_1_data_89C: character model table (fn_1_52E0) */
typedef struct SdCharData_s {
    u32 dataNum; /* 0x0 */
    u32 unk4;    /* 0x4: DATANUM or HU_DATANUM_NONE */
    s32 unk8;
    s32 unkC;
    s32 unk10;
    s32 unk14;
    s32 unk18;
} SDCHARDATA; /* 0x1C */

/* a machine's models (garage lbl_1_bss_67C[2], garagesave lbl_1_bss_770, picture
 * lbl_1_bss_AA4, ending lbl_1_bss_18F4, stack locals); built by fn_1_42E0/fn_1_44E4 */
typedef struct SdMachineMdl_s {
    char name[17];       /* 0x00: strcpy / NameEnterMain */
    s16 partNo[4];       /* 0x12: body, tire, char, hook (0x40 = no hook); -1 = none */
    HU3DMODELID bodyMdl; /* 0x1A */
    HU3DMODELID tireMdl[4]; /* 0x1C */
    HU3DMODELID charMdl; /* 0x24 */
    HU3DMODELID hookMdl; /* 0x26 */
    float ofsY;          /* 0x28: body height (fn_1_5390), added to the model's Y */
} SDMACHINEMDL; /* 0x2C */

/* tournament.c: the bracket, kept in mgModeWork (fn_1_1F21C fills it, fn_1_1C260 advances it) */
typedef struct SdTourWork_s {
    u8 charNo[8]; /* 0x0: seat -> opponent id (32..42; seat 0 = the player's GWSDMACHINE.charNo; 43 = empty) */
    u8 round[8];  /* 0x8: seat -> matches won (0..3) */
} SDTOURWORK;
#define SDTOUR ((SDTOURWORK *)mgModeWork)

/* ending.c lbl_1_bss_C4C[50]: one falling confetti piece (fn_1_25198 spawns, fn_1_24F14 moves,
 * fn_1_24DC0 draws) */
typedef struct SdConfetti_s {
    s32 active;     /* 0x00 */
    s32 landed;     /* 0x04: on the floor; cleared after 3 more frames */
    HuVecF pos;     /* 0x08 */
    HuVecF vel;     /* 0x14 */
    HuVecF rot;     /* 0x20 */
    HuVecF rotVel;  /* 0x2C */
    GXColor color;  /* 0x38: copied into every material's color */
    s32 time;       /* 0x3C */
} SDCONFETTI; /* 0x40 */

/* ending.c lbl_1_bss_C40: the confetti system */
typedef struct SdConfettiSys_s {
    HU3DMODELID mdl;  /* 0x0: piece model (sdd1 30), display off */
    HU3DMODELID hook; /* 0x2: hook model drawing every active piece (fn_1_24DC0) */
    float floorY;     /* 0x4 */
    s32 num;          /* 0x8: active pieces */
} SDCONFETTISYS; /* 0xC */

